package com.srenterprises.security;
import com.srenterprises.repository.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.*; import org.springframework.security.config.http.*; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.*; import org.springframework.security.web.*; import org.springframework.security.web.authentication.*; import org.springframework.web.cors.*; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.authority.*; import org.springframework.security.core.context.*; import java.io.*;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain security(HttpSecurity h, JwtService jwt, UserRepository users) throws Exception { h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/health","/api/auth/**","/api/products/**","/api/categories/**").permitAll().requestMatchers("/api/admin/**").hasAnyRole("SUPER_ADMIN","ADMIN").anyRequest().authenticated()).addFilterBefore(new OncePerRequestFilter(){protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var u=users.findByEmailIgnoreCase(jwt.email(h.substring(7))).filter(x->x.active).orElse(null);if(u!=null){var auth=new UsernamePasswordAuthenticationToken(u.email,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.role)));SecurityContextHolder.getContext().setAuthentication(auth);}}catch(Exception ignored){} c.doFilter(r,p);}},UsernamePasswordAuthenticationFilter.class); return h.build(); } @Bean CorsConfigurationSource cors(@org.springframework.beans.factory.annotation.Value("${app.cors-origins}") String origins){var c=new CorsConfiguration();c.setAllowedOrigins(java.util.List.of(origins.split(",")));c.setAllowedMethods(java.util.List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(java.util.List.of("Authorization","Content-Type"));var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
